class Solution:
    def countSubstrings(self, s: str) -> int:
        total_substrings = 0
        n = len(s)

        for i in range(n):
            for j in range(i + 1, n + 1):
                substring = s[i:j]
                last_digit = int(substring[-1])

                if last_digit != 0 and int(substring) % last_digit == 0:
                    total_substrings += 1

        return total_substrings

